resource "aws_iam_user_policy_attachment" "telemetry_lake_attachment" {
  user       = "svc-telemetry-ingest"
  policy_arn = "arn:aws:iam::112233445566:policy/DataLakeIngestPolicy"
}
```

You add the `prevent_destroy` meta-argument inside a `lifecycle` block:

```hcl
resource "aws_iam_user_policy_attachment" "telemetry_lake_attachment" {
  user       = "svc-telemetry-ingest"
  policy_arn = "arn:aws:iam::112233445566:policy/DataLakeIngestPolicy"

  lifecycle {
    prevent_destroy = true
  }
}
```

```hcl
resource "aws_iam_user_policy_attachment" "user_policy_binding_telemetry_datalake" {
  user       = "svc-telemetry-ingest"
  policy_arn = "arn:aws:iam::112233445566:policy/DataLakeIngestPolicy"

  lifecycle {
    prevent_destroy = true
  }
}
```

You can use the `count` meta-argument:

```hcl
resource "aws_iam_user_policy_attachment" "user_policy_binding_telemetry_datalake" {
  count      = var.enable_datalake_access ? 1 : 0
  user       = "svc-telemetry-ingest"
  policy_arn = "arn:aws:iam::112233445566:policy/DataLakeIngestPolicy"

  lifecycle {
    prevent_destroy = true
  }
}
```

```hcl
data "aws_iam_user" "target_user" {
  user_name = "svc-telemetry-ingest"
}

resource "aws_iam_user_policy_attachment" "user_policy_binding_telemetry_datalake" {
  count      = var.enable_datalake_access ? 1 : 0
  user       = data.aws_iam_user.target_user.user_name
  policy_arn = "arn:aws:iam::112233445566:policy/DataLakeIngestPolicy"

  lifecycle {
    precondition {
      condition     = data.aws_iam_user.target_user.permissions_boundary_arn == "arn:aws:iam::112233445566:policy/RestrictedBoundary"
      error_message = "User missing required permissions boundary."
    }
  }
}
```

When `count = 0`, zero instances of the resource are created, so Terraform skips the resource block entirely and does not evaluate the `precondition`.

```hcl
# Precondition runs only when count > 0 (var.enable_datalake_access is true).
# If count is 0, this block is omitted from the plan and no check occurs.
resource "aws_iam_user_policy_attachment" "user_policy_binding_telemetry_datalake" {
  count      = var.enable_datalake_access ? 1 : 0
  user       = data.aws_iam_user.target_user.user_name
  policy_arn = "arn:aws:iam::112233445566:policy/DataLakeIngestPolicy"

  lifecycle {
    precondition {
      condition     = data.aws_iam_user.target_user.permissions_boundary_arn == "arn:aws:iam::112233445566:policy/RestrictedBoundary"
      error_message = "User missing required permissions boundary."
    }
  }
}
