import pytest
from vanguard.parsers import (
    parse_tcx_packet,
    TemperatureOutOfBoundsError,
    CorruptTelemetryException,
    ChecksumMismatchError,
    LowBatteryWarning,
)

@pytest.mark.parametrize(
    "temp_raw, humidity, battery, corrupt_chk, expected_exc, expected_warn",
    [
        (200, 50, 80, False, None, None),
        (200, 50, 3, False, None, LowBatteryWarning),
        (851, 50, 80, False, TemperatureOutOfBoundsError, None),
        (-401, 50, 80, False, TemperatureOutOfBoundsError, None),
        (200, 101, 80, False, CorruptTelemetryException, None),
        (200, 50, 80, True, ChecksumMismatchError, None),
    ],
)
def test_tcx_packet_ingestion(
    make_tcx_packet, temp_raw, humidity, battery, corrupt_chk, expected_exc, expected_warn
):
    pkt = bytearray(make_tcx_packet(temp_raw, humidity, battery))
    if corrupt_chk:
        pkt[-1] ^= 0xFF

    if expected_exc:
        with pytest.raises(expected_exc):
            parse_tcx_packet(bytes(pkt))
    elif expected_warn:
        with pytest.warns(expected_warn):
            parse_tcx_packet(bytes(pkt))
    else:
        res = parse_tcx_packet(bytes(pkt))
        assert res == {"temp_c": temp_raw / 10.0, "humidity": humidity, "battery": battery}
