import pytest
from iot_ingest.decoder import (
    decode_telematics_frame,
    FrameTooShortError,
    ChecksumMismatchError,
    InvalidSyncByteError,
)

def make_frame(payload: bytes, bad_chk: bool = False) -> str:
    chk = 0
    for b in payload:
        chk ^= b
    chk = (chk ^ 0xFF) if bad_chk else chk
    return (b"\xaa" + payload + bytes([chk])).hex()

def test_valid_frame():
    payload = b"\x00\x01\x65\xec\x00\x00\x00\xfa"
    res = decode_telematics_frame(make_frame(payload))
    assert res == {"device_id": 1, "timestamp": 1710006272, "speed_knots": 25.0}

def test_frame_too_short():
    with pytest.raises(FrameTooShortError):
        decode_telematics_frame("AA0001")

def test_invalid_sync_byte():
    with pytest.raises(InvalidSyncByteError):
        decode_telematics_frame("FF" + "00" * 8)

def test_checksum_mismatch():
    with pytest.raises(ChecksumMismatchError):
        decode_telematics_frame(make_frame(b"\x00\x01\x65\xec\x00\x00\x00\xfa", bad_chk=True))
