```python
import hmac
import hashlib
import time
import pytest
from acmepay.parser import WebhookEnvelopeParser, StaleTimestampError, InvalidSignatureError

SECRET = "k_sec_live_99"
NOW = 1714560000

def make_sig(ts: int, body: str, secret: str = SECRET) -> str:
    content = f"{ts}.{body}".encode("utf-8")
    digest = hmac.new(secret.encode("utf-8"), content, hashlib.sha256).hexdigest()
    return f"v1={digest}"

@pytest.fixture
def parser():
    return WebhookEnvelopeParser(secret=SECRET)

def test_valid_payload(parser, monkeypatch):
    monkeypatch.setattr(time, "time", lambda: NOW)
    body = '{"event":"payment.success"}'
    headers = {"X-Acme-Timestamp": str(NOW - 10), "X-Acme-Signature": make_sig(NOW - 10, body)}
    env = parser.parse(body, headers)
    assert env.payload == {"event": "payment.success"}

def test_stale_timestamp(parser, monkeypatch):
    monkeypatch.setattr(time, "time", lambda: NOW)
    body = '{"event":"ping"}'
    headers = {"X-Acme-Timestamp": str(NOW - 301), "X-Acme-Signature": make_sig(NOW - 301, body)}
    with pytest.raises(StaleTimestampError):
        parser.parse(body, headers)

def test_future_timestamp_drift(parser, monkeypatch):
    monkeypatch.setattr(time, "time", lambda: NOW)
    body = '{"event":"ping"}'
    headers = {"X-Acme-Timestamp": str(NOW + 61), "X-Acme-Signature": make_sig(NOW + 61, body)}
    with pytest.raises(StaleTimestampError):
        parser.parse(body, headers)

def test_invalid_signature(parser, monkeypatch):
    monkeypatch.setattr(time, "time", lambda: NOW)
    body = '{"event":"ping"}'
    headers = {"X-Acme-Timestamp": str(NOW), "X-Acme-Signature": "v1=deadbeef001122"}
    with pytest.raises(InvalidSignatureError):
        parser.parse(body, headers)
