import pytest
from validator import (
    WebhookSignatureValidator, MissingSignatureError,
    MalformedHeaderError, SignatureMismatchError
)

SECRET = b"test-secret-key-0123456789"
PAYLOAD = b'{"event":"order.created","id":101}'
VALID_SIG = "sha256=2b55f1f94c399b6df65c84a860714811a2f64604e38e8ec4d8f07096b1b5e396"

@pytest.mark.parametrize("header", [None, ""])
def test_missing_signature(header):
    with pytest.raises(MissingSignatureError):
        WebhookSignatureValidator.verify(header, PAYLOAD, SECRET)

@pytest.mark.parametrize("bad_header", ["sha256=", "sha1=abcd", "sha256=xyz", "sha256=" + "a" * 63])
def test_malformed_signature(bad_header):
    with pytest.raises(MalformedHeaderError):
        WebhookSignatureValidator.verify(bad_header, PAYLOAD, SECRET)

def test_signature_mismatch():
    with pytest.raises(SignatureMismatchError):
        WebhookSignatureValidator.verify("sha256=" + "0" * 64, PAYLOAD, SECRET)

def test_valid_signature():
    assert WebhookSignatureValidator.verify(VALID_SIG, PAYLOAD, SECRET) is True
