```python
from datetime import date, timedelta
import pytest
from clearing.validators import (
    BatchSettlementProcessor,
    PastSettlementDateError,
    LimitExceededError,
    InvalidMandateError,
)

@pytest.fixture
def processor():
    return BatchSettlementProcessor(scheme="CORE")

@pytest.fixture
def base_instruction():
    return {
        "mandate_id": "MND-98421",
        "mandate_seq": "RCUR",
        "amount": 1250.00,
        "settlement_date": date.today() + timedelta(days=3),
    }

def test_validate_instruction_success(processor, base_instruction):
    assert processor.validate_instruction(base_instruction) is True

def test_validate_instruction_past_settlement_date(processor, base_instruction):
    base_instruction["settlement_date"] = date.today() + timedelta(days=1)
    with pytest.raises(PastSettlementDateError):
        processor.validate_instruction(base_instruction)

def test_validate_instruction_limit_exceeded(processor, base_instruction):
    base_instruction["amount"] = 50000.01
    with pytest.raises(LimitExceededError):
        processor.validate_instruction(base_instruction)

def test_validate_instruction_invalid_mandate_seq(processor, base_instruction):
    base_instruction["mandate_seq"] = "INVALID"
    with pytest.raises(InvalidMandateError):
        processor.validate_instruction(base_instruction)
